#include <vector>
#include <unordered_map>
#include <algorithm>

class Solution {
public:
    std::vector<std::vector<int>> diagonalSort(std::vector<std::vector<int>>& mat) {
        int m = mat.size(), n = mat[0].size();
        std::unordered_map<int, std::vector<int>> diags;
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                diags[r - c].push_back(mat[r][c]);
            }
        }
        for (auto& [k, v] : diags) {
            std::sort(v.rbegin(), v.rend());
        }
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                mat[r][c] = diags[r - c].back();
                diags[r - c].pop_back();
            }
        }
        return mat;
    }
};

import java.util.*;

class Solution {
    public int[][] diagonalSort(int[][] mat) {
        int m = mat.length, n = mat[0].length;
        Map<Integer, List<Integer>> diags = new HashMap<>();
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                diags.computeIfAbsent(r - c, k -> new ArrayList<>()).add(mat[r][c]);
            }
        }
        for (List<Integer> list : diags.values()) {
            list.sort(Collections.reverseOrder());
        }
        for (int r = 0; r < m; r++) {
            for (int c = 0; c < n; c++) {
                List<Integer> list = diags.get(r - c);
                mat[r][c] = list.remove(list.size() - 1);
            }
        }
        return mat;
    }
}

var diagonalSort = function(mat) {
    const m = mat.length, n = mat[0].length;
    const diags = new Map();
    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            const k = r - c;
            if (!diags.has(k)) diags.set(k, []);
            diags.get(k).push(mat[r][c]);
        }
    }
    for (const v of diags.values()) {
        v.sort((a, b) => b - a);
    }
    for (let r = 0; r < m; r++) {
        for (let c = 0; c < n; c++) {
            mat[r][c] = diags.get(r - c).pop();
        }
    }
    return mat;
};
